package ec.dmt.admin.school;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/students") public class StudentController { private final StudentRepository repo; private final SchoolParallelRepository parallels; public StudentController(StudentRepository repo,SchoolParallelRepository parallels){this.repo=repo;this.parallels=parallels;} @GetMapping public List<View> list(){return repo.findAll().stream().map(View::of).toList();} @PostMapping public ResponseEntity<View> create(@Valid @RequestBody Input in){Student s=repo.save(new Student(in.biometricUserId().trim(),in.firstName().trim(),in.lastName().trim(),parallel(in.parallelId()),in.active()));return ResponseEntity.status(201).body(View.of(s));} @PutMapping("/{id}") public View update(@PathVariable Long id,@Valid @RequestBody Input in){Student s=find(id);s.update(in.biometricUserId().trim(),in.firstName().trim(),in.lastName().trim(),parallel(in.parallelId()),in.active());return View.of(repo.save(s));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){repo.delete(find(id));} private Student find(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Estudiante no encontrado"));} private SchoolParallel parallel(Long id){return parallels.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Paralelo no encontrado"));} public record Input(@NotBlank String biometricUserId,@NotBlank String firstName,@NotBlank String lastName,@NotNull Long parallelId,boolean active){} public record View(Long id,String biometricUserId,String firstName,String lastName,Long parallelId,String parallelName,String courseName,boolean active){static View of(Student s){SchoolParallel p=s.getParallel();return new View(s.getId(),s.getBiometricUserId(),s.getFirstName(),s.getLastName(),p.getId(),p.getName(),p.getCourse().getName(),s.isActive());}} }
